pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }
    function testFuzz_property(uint256 _val) public {
        bool ok;
        try c.SetMinSum(_val) { ok = true; } catch { ok = false; }
        assertTrue(ok && c.MinSum() == _val);
    }
}
